From 9cbc861095375793a69858f91f3ac4e817f320f0 Mon Sep 17 00:00:00 2001
From: Andy Shevchenko <andriy.shevchenko@linux.intel.com>
Date: Thu, 5 Aug 2021 14:26:19 +0300
Subject: [PATCH] leds: lgm-sso: Propagate error codes from callee to caller

The one of the latest change to the driver reveals the problem that
the error codes from callee aren't propagated to the caller of
__sso_led_dt_parse(). Fix this accordingly.

Fixes: 9999908ca1ab ("leds: lgm-sso: Put fwnode in any case during ->probe()")
Fixes: c3987cd2bca3 ("leds: lgm: Add LED controller driver for LGM SoC")
Reported-by: kernel test robot <lkp@intel.com>
Signed-off-by: Andy Shevchenko <andriy.shevchenko@linux.intel.com>
Signed-off-by: Pavel Machek <pavel@ucw.cz>

diff --git a/drivers/leds/blink/leds-lgm-sso.c b/drivers/leds/blink/leds-lgm-sso.c
index e47c47e421d6..fd8b7573285a 100644
--- a/drivers/leds/blink/leds-lgm-sso.c
+++ b/drivers/leds/blink/leds-lgm-sso.c
@@ -640,7 +640,7 @@ __sso_led_dt_parse(struct sso_led_priv *priv, struct fwnode_handle *fw_ssoled)
 							      fwnode_child,
 							      GPIOD_ASIS, NULL);
 		if (IS_ERR(led->gpiod)) {
-			dev_err_probe(dev, PTR_ERR(led->gpiod), "led: get gpio fail!\n");
+			ret = dev_err_probe(dev, PTR_ERR(led->gpiod), "led: get gpio fail!\n");
 			goto __dt_err;
 		}

@@ -660,8 +660,11 @@ __sso_led_dt_parse(struct sso_led_priv *priv, struct fwnode_handle *fw_ssoled)
 			desc->panic_indicator = 1;

 		ret = fwnode_property_read_u32(fwnode_child, "reg", &prop);
-		if (ret != 0 || prop >= SSO_LED_MAX_NUM) {
+		if (ret)
+			goto __dt_err;
+		if (prop >= SSO_LED_MAX_NUM) {
 			dev_err(dev, "invalid LED pin:%u\n", prop);
+			ret = -EINVAL;
 			goto __dt_err;
 		}
 		desc->pin = prop;
@@ -697,7 +700,8 @@ __sso_led_dt_parse(struct sso_led_priv *priv, struct fwnode_handle *fw_ssoled)
 				desc->brightness = LED_FULL;
 		}

-		if (sso_create_led(priv, led, fwnode_child))
+		ret = sso_create_led(priv, led, fwnode_child);
+		if (ret)
 			goto __dt_err;
 	}

@@ -709,7 +713,7 @@ __sso_led_dt_parse(struct sso_led_priv *priv, struct fwnode_handle *fw_ssoled)
 	list_for_each_entry(led, &priv->led_list, list)
 		sso_led_shutdown(led);

-	return -EINVAL;
+	return ret;
 }

 static int sso_led_dt_parse(struct sso_led_priv *priv)
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the failure to propagate error codes from the function `__sso_led_dt_parse`, which meant that errors occurring during GPIO retrieval and LED creation were not communicated back to the caller. This lack of error handling could lead to undefined behavior or incorrect assumptions about the success of operations in the driver.

        Commit message:
        leds: lgm-sso: Propagate error codes from callee to caller

The one of the latest change to the driver reveals the problem that
the error codes from callee aren't propagated to the caller of
__sso_led_dt_parse(). Fix this accordingly.

Fixes: 9999908ca1ab ("leds: lgm-sso: Put fwnode in any case during ->probe()")
Fixes: c3987cd2bca3 ("leds: lgm: Add LED controller driver for LGM SoC")
Reported-by: kernel test robot <lkp@intel.com>
Signed-off-by: Andy Shevchenko <andriy.shevchenko@linux.intel.com>
Signed-off-by: Pavel Machek <pavel@ucw.cz>  

        Patch:

 static int
 __sso_led_dt_parse(struct sso_led_priv *priv, struct fwnode_handle *fw_ssoled)
 {
 	struct fwnode_handle *fwnode_child;
 	struct device *dev = priv->dev;
 	struct sso_led_desc *desc;
 	struct sso_led *led;
 	const char *tmp;
 	u32 prop;
 	int ret;

 	fwnode_for_each_child_node(fw_ssoled, fwnode_child) {
 		led = devm_kzalloc(dev, sizeof(*led), GFP_KERNEL);
 		if (!led) {
 			ret = -ENOMEM;
 			goto __dt_err;
 		}

 		INIT_LIST_HEAD(&led->list);
 		led->priv = priv;
 		desc = &led->desc;

 		led->gpiod = devm_fwnode_get_gpiod_from_child(dev, NULL,
 							      fwnode_child,
 							      GPIOD_ASIS, NULL);
 		if (IS_ERR(led->gpiod)) {
-			dev_err_probe(dev, PTR_ERR(led->gpiod), "led: get gpio fail!\n");
+			ret = dev_err_probe(dev, PTR_ERR(led->gpiod), "led: get gpio fail!\n");
 			goto __dt_err;
 		}

 		fwnode_property_read_string(fwnode_child,
 					    "linux,default-trigger",
 					    &desc->default_trigger);

 		if (fwnode_property_present(fwnode_child,
 					    "retain-state-suspended"))
 			desc->retain_state_suspended = 1;

 		if (fwnode_property_present(fwnode_child,
 					    "retain-state-shutdown"))
 			desc->retain_state_shutdown = 1;

 		if (fwnode_property_present(fwnode_child, "panic-indicator"))
 			desc->panic_indicator = 1;

 		ret = fwnode_property_read_u32(fwnode_child, "reg", &prop);
-		if (ret != 0 || prop >= SSO_LED_MAX_NUM) {
+		if (ret)
+			goto __dt_err;
+		if (prop >= SSO_LED_MAX_NUM) {
 			dev_err(dev, "invalid LED pin:%u\n", prop);
+			ret = -EINVAL;
 			goto __dt_err;
 		}
 		desc->pin = prop;

 		if (fwnode_property_present(fwnode_child, "intel,sso-hw-blink"))
 			desc->hw_blink = 1;

 		desc->hw_trig = fwnode_property_read_bool(fwnode_child,
 							  "intel,sso-hw-trigger");
 		if (desc->hw_trig) {
 			desc->default_trigger = NULL;
 			desc->retain_state_shutdown = 0;
 			desc->retain_state_suspended = 0;
 			desc->panic_indicator = 0;
 			desc->hw_blink = 0;
 		}

 		if (fwnode_property_read_u32(fwnode_child,
 					     "intel,sso-blink-rate-hz", &prop)) {
 			/* default first freq rate */
 			desc->freq_idx = 0;
 			desc->blink_rate = priv->freq[desc->freq_idx];
 		} else {
 			desc->freq_idx = sso_get_blink_rate_idx(priv, prop);
 			if (desc->freq_idx == -1)
 				desc->freq_idx = MAX_FREQ_RANK - 1;

 			desc->blink_rate = priv->freq[desc->freq_idx];
 		}

 		if (!fwnode_property_read_string(fwnode_child, "default-state", &tmp)) {
 			if (!strcmp(tmp, "on"))
 				desc->brightness = LED_FULL;
 		}

-		if (sso_create_led(priv, led, fwnode_child))
+		ret = sso_create_led(priv, led, fwnode_child);
+		if (ret)
 			goto __dt_err;
 	}

 	return 0;

 __dt_err:
 	fwnode_handle_put(fwnode_child);
 	/* unregister leds */
 	list_for_each_entry(led, &priv->led_list, list)
 		sso_led_shutdown(led);

-	return -EINVAL;
+	return ret;
 }



